<?php require __DIR__.'/bootstrap.php';require_login();$where=is_admin()?'':' WHERE c.owner_id=?';$q=db()->prepare('SELECT c.*,u.name owner_name FROM cars c JOIN users u ON u.id=c.owner_id'.$where.' ORDER BY c.created_at DESC');$q->execute(is_admin()?[]:[current_user()['id']]);$cars=$q->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['car_id']??0);$action=$_POST['action']??'';$check=db()->prepare('SELECT id FROM cars WHERE id=?'.(is_admin()?'':' AND owner_id=?'));$check->execute(is_admin()?[$id]:[$id,current_user()['id']]);if(!$check->fetch()){http_response_code(403);exit('Not allowed.');}if($action==='sold')db()->prepare('UPDATE cars SET status="sold" WHERE id=?')->execute([$id]);if($action==='delete'){ $imgs=db()->prepare('SELECT image_path FROM car_images WHERE car_id=?');$imgs->execute([$id]);foreach($imgs as $im){$file=__DIR.'/'.$im['image_path'];if(is_file($file))unlink($file);}db()->prepare('DELETE FROM cars WHERE id=?')->execute([$id]);}flash('Listing updated.');redirect('manage-cars.php');}page_top('Manage cars');?><h1><?=is_admin()?'All listings':'My listings'?></h1><p><a class="button" href="add-car.php">Add car</a></p><table class="table"><thead><tr><th>Car</th><?php if(is_admin()):?><th>Owner</th><?php endif?><th>Price</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($cars as $car):?><tr><td><?=e($car['title'])?></td><?php if(is_admin()):?><td><?=e($car['owner_name'])?></td><?php endif?><td>₹<?=number_format((float)$car['price'])?></td><td><?=e($car['status'])?></td><td><form class="actions" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="car_id" value="<?=$car['id']?>"><?php if($car['status']!=='sold'):?><button class="button small" name="action" value="sold">Mark sold</button><?php endif?><button class="button small danger" name="action" value="delete" onclick="return confirm('Delete this car?')">Delete</button></form></td></tr><?php endforeach?></tbody></table><?php page_bottom();
